VALUES (61617, 'tt3718778', NULL, 'Over the Garden Wall', 'Over the Garden Wall', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/m3lU8n7WxzMecxKZcqhq5y5ESy.jpg', 'https://image.tmdb.org/t/p/original/hozufHEzqIRpqJrlyGDqnsyFrAQ.jpg', 'Two brothers, Wirt and Greg, find themselves lost in the Unknown; a strange forest adrift in time. With the help of a wise old Woodsman and a foul-tempered bluebird named Beatrice, Wirt and Greg must travel across this strange land, in hope of finding their way home. Join them as they encounter surprises and obstacles on their journey through the wood.', NULL, NULL, 18.0827, 8.572, 0, 6.6028983050847458e+01, '2026-07-15 12:01:52', '2026-11-07 20:24:11')
